for c in independent['cases']:assert sha(O/'independent-fixtures'/(c['case']+'.sqlite'))==c['database_sha256_before_after']
author=read(O/'author-replay/controlled-validation-result.json');assert len(author['cases'])==9 and author['all_expected_outcomes']
put('independent.invocation.json',{'source':'reconstructed_from_actual_exec_tool_command_and_result','argv':[sys.executable,'-X','utf8',str(O/'independent.py')],'exit':0,'stdout':{'cases':23,'accepted_valid':4,'rejected_invalid':19,'all_expected_outcomes':True,'actual_extra_go_oracle':1},'cwd':'D:/作品集/ResearchOS','database_connections_guarded_to':'C-only exact fixture mode=ro URI','launcher_executed':False})
put('verification-final.json',{'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_refs_unchanged':len(before['refs']),'drift':drift,'previous_review':{'path':str(p),'sha256':sha(p)},'C_fixture_databases':32,'go_oracle_comparisons':4,'original_database_opened':False,'D_writes':0})
put('report.json',{'schema':'researchos.observer-v3-independent-review/1','verdict':'APPROVE_ROOT_READONLY_HELPER_SCOPE','reviewer':'/root/runtime_identity_boundary','source_manifest_sha256':before['source_manifest_sha256'],'source_observe_sha256':sha(O/'frozen-source/observe.py'),'blocking_findings':[],'closed_findings':['OBSV2-R1-P1','OBSV2-R2-P1','OBSV2-R3-P2'],'author_case_replay':{'db_cases':9,'valid_accepted':3,'invalid_rejected':6,'go_oracle':3,'all_expected_outcomes':True},'independent_cases':{'db_cases':23,'valid_accepted':4,'invalid_rejected':19,'go_oracle':1,'all_expected_outcomes':True},'database_protection':{'mode':'ro','query_only':True,'transaction':'BEGIN/ROLLBACK','exact_C_fixture_connection_guard':True,'all_fixture_hashes_unchanged':True,'original_database_opened':False},'limits':['Exact legal producer scalar subset only, not general JCS validator','Future-effective budget revision fail-closed; no historical domain_versions fallback','Task must still reference original active_run_id','Request seconds remaining is evidence, not collector-issued CONFIRM approval','Resource body output is not generic privacy certification','Electron launcher capability not exercised; no Core/worker/verifier exit inference'],'missing':['private_management_stdout_frames','native_verifier_stderr','native_verifier_numeric_wait','actual original request and Run observation','actual Electron native wait'],'source_modified':False,'canonical_modified':False,'launcher_executed':False,'product_launches':0,'original_sqlite_access':False,'real_secrets_accessed':False,'network_calls':0,'model_calls':0,'tool_dispatches':0,'D_writes':0,'formal_increment':0,'product_acceptance':False,'report_md_sha256':sha(O/'report.md'),'formal_mirror_target':'execution/v2.4/receipts/W05/W05-99/normal_qualification_observer_v3_review_codex/20261012-current-chat'})
members=[{'path':p.relative_to(O).as_posix(),'bytes':p.stat().st_size,'sha256':sha(p)} for p in sorted(O.rglob('*')) if p.is_file() and p.name not in ['manifest.json','seal.json']]
