put('seal.json',{'report_sha256':sha(O/'report.json'),'report_md_sha256':sha(O/'report.md'),'manifest_sha256':sha(O/'manifest.json')})
print((O/'seal.json').read_text());print(json.dumps({'members':len(members)}))
